@foreach($brandsData['tables'] as $table)<section class="br-table-section"><h4>{{ $table['title'] }} ({{ $table['total'] }})</h4><div class="br-table-wrap" role="region" aria-label="{{ $table['title'] }}" tabindex="0"><table class="br-table"><thead><tr>@foreach($table['columns'] as $column)<th scope="col">{{ $column['label'] }}</th>@endforeach<th scope="col">Details</th></tr></thead><tbody>@forelse($table['rows'] as $row)<tr>@foreach($table['columns'] as $column)@php($value=$row[$column['key']]??null)<td class="{{ $column['format']==='rich'?'br-rich-cell':'' }}">@if($column['format']==='rich')<div class="weekly-rich-content">{!! $value?:'Not recorded' !!}</div>@elseif($column['format']==='date'){{ $value?\Carbon\Carbon::parse($value)->format('d M Y'):'Not recorded' }}@elseif(in_array($column['format'],['number','percent'])){{ $value===null?'Not recorded':number_format((float)$value, is_float($value)?1:0) }}{{ $value!==null&&$column['format']==='percent'?'%':'' }}@else{{ $value??'Not recorded' }}@endif</td>@endforeach<td>@if($row['source_type']??null)<button type="button" data-br-detail="{{ $row['source_type'] }}:{{ $row['id'] }}">View Details</button>@endif</td></tr>@empty<tr><td colspan="{{ count($table['columns'])+1 }}">No saved entries match this period and staff selection. Choose another reporting period to see earlier work.</td></tr>@endforelse</tbody></table></div></section>@endforeach
